import * as assert from 'node:assert';
import * as vscode from 'vscode';
import { TOOLS, type CatalogTool } from '../../catalog';

const EXTENSION_ID = 'redbison.redbison-tools';

function tool(id: string): CatalogTool {
  const found = TOOLS.find((t) => t.id === id);
  assert.ok(found, `${id} is not in the catalog`);
  return found;
}

let docs: Record<string, string> | undefined;
async function loadDocs(): Promise<Record<string, string>> {
  if (!docs) {
    const ext = vscode.extensions.getExtension(EXTENSION_ID)!;
    const uri = vscode.Uri.joinPath(ext.extensionUri, 'media', 'docs.json');
    docs = JSON.parse(Buffer.from(await vscode.workspace.fs.readFile(uri)).toString('utf8'));
  }
  return docs!;
}

async function runOn(content: string, command: string): Promise<string> {
  const doc = await vscode.workspace.openTextDocument({ content, language: 'plaintext' });
  const editor = await vscode.window.showTextDocument(doc);
  editor.selection = new vscode.Selection(doc.positionAt(0), doc.positionAt(content.length));
  await vscode.commands.executeCommand(command);
  return doc.getText();
}

